import{c as i,$ as t,Q as n,j as s,o,m as d,g as p}from"./chunks/framework.CWBTDBPu.js";const T=JSON.parse('{"title":"YuTeleport 插件介绍","description":"","frontmatter":{"title":"YuTeleport 插件介绍"},"headers":[],"relativePath":"plugins/items/yu-teleport/index.md","filePath":"plugins/items/yu-teleport/index.md"}'),h={name:"plugins/items/yu-teleport/index.md"},u={class:"quick-actions"};function m(g,e,P,_,f,y){const a=t("PluginMeta"),r=t("CopyMarkdownButton"),c=t("CopyLLMButton"),l=t("PluginServerShowcase");return n(),s("div",null,[o(a,{slug:"yu-teleport"}),e[0]||(e[0]=d('<div class="quick-actions"><a class="tool-button" href="https://github.com/vicuna-main/YuTeleportIssueReport" target="_blank" rel="noopener noreferrer">Bug / Issue 反馈</a><a class="tool-button" href="https://modrinth.com/plugin/yuteleport" target="_blank" rel="noopener noreferrer">Modrinth 下载</a><a class="tool-button" href="https://qm.qq.com/q/xiwJYBYdh0" target="_blank" rel="noopener noreferrer">官方 QQ 交流群</a><a class="tool-button" href="https://afdian.com/a/vicuna" target="_blank" rel="noopener noreferrer">爱发电支持作者</a></div><h2 id="文档入口" tabindex="-1">文档入口 <a class="header-anchor" href="#文档入口" aria-label="Permalink to &quot;文档入口&quot;">​</a></h2><p>YuTeleport <code>2.0.0.0</code>，简称 YuTP，是从旧 YuRTP 随机传送插件演进而来的跨版本安全传送套件。它把随机传送、warp、home、tpa、坐标分享、经济扣费、权限分组、Folia/Paper 兼容、PlaceholderAPI 与公开 Java API 放进同一套传送管线。</p><div class="doc-card-grid"><a class="doc-mini-card" href="install"><strong>安装部署</strong><span>构建、放置 jar、首次启动、可选依赖、升级检查和卸载路径</span></a><a class="doc-mini-card" href="commands"><strong>命令手册</strong><span>/yuteleport、/ytp、/rtp、warp、home、tpa 与坐标分享命令</span></a><a class="doc-mini-card" href="config"><strong>配置说明</strong><span>模块开关、世界规则、经济、冷却、预缓存、音效标题和权限组</span></a><a class="doc-mini-card" href="permissions"><strong>权限节点</strong><span>随机传送、warp、home、tpa、分享、绕过权限与动态上限</span></a><a class="doc-mini-card" href="placeholders"><strong>PlaceholderAPI</strong><span>%yuteleport_*% 状态、冷却、模块、世界、费用和统计变量</span></a><a class="doc-mini-card" href="events"><strong>Bukkit 事件</strong><span>开始、目标点、取消与完成四个泛化传送生命周期事件</span></a><a class="doc-mini-card" href="api"><strong>Java API</strong><span>RTP、warp、home、tpa、冷却、列表、费用、快照和平台检测</span></a><a class="doc-mini-card" href="faq"><strong>常见问题</strong><span>命令兼容、经济、世界限制、安全点、PAPI、Folia 与配置升级排查</span></a></div>',4)),p("div",u,[o(r,{slug:"yu-teleport"}),o(c,{slug:"yu-teleport"})]),e[1]||(e[1]=d('<h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>广版本与混合端适配</td><td>面向 Minecraft <code>1.8.x-1.26.x</code>，覆盖 Spigot、Paper、Paper 衍生端、Folia，并兼顾 Mohist、Arclight、Youer 等混合端运行环境。</td></tr><tr><td>随机传送</td><td><code>/yuteleport</code>、<code>/ytp</code> 与 <code>/rtp</code> 共用安全点搜索，支持方形/圆形范围、世界中心点、高度限制、生物群系黑白名单和后台预缓存。</td></tr><tr><td>warp 模块</td><td>支持 <code>/warp</code>、<code>/setwarp</code>、<code>/delwarp</code>，可创建私有、公开或 restricted warp，并通过权限控制数量和可见性。</td></tr><tr><td>home 模块</td><td>支持 <code>/home</code>、<code>/homes</code>、<code>/sethome</code>、<code>/delhome</code>，可公开 home，支持按权限和分组扩展 home 数量。</td></tr><tr><td>tpa 模块</td><td>支持 <code>/tpa</code>、<code>/tpahere</code>、<code>/tpaccept</code>、<code>/tpdeny</code>、<code>/tpacancel</code>、<code>/tpaignore</code> 与全服 tpahere 请求。</td></tr><tr><td>坐标分享</td><td>传送成功后可点击分享当前位置，其他玩家可在有效期内点击传送到该坐标。</td></tr><tr><td>经济扣费</td><td>可选接入 Vault 或 PlayerPoints，RTP、warp、home、tpa、分享可分别配置费用。</td></tr><tr><td>冷却与等待</td><td>各模块独立冷却和等待时间，支持持久化冷却，移动、受伤、交互、聊天和命令可按项打断。</td></tr><tr><td>权限组覆盖</td><td>通过 <code>groups</code> 与 <code>yuteleport.group.&lt;组名&gt;</code> 覆盖不同玩家组的冷却、费用、home 数量和 warp 数量。</td></tr><tr><td>视听反馈</td><td>支持聊天、BossBar、ActionBar 倒计时，内置标题、粒子、音效、交互式点击重试和坐标悬停。</td></tr><tr><td>插件联动</td><td>公开 <code>YuTeleportApi</code>，通过 Bukkit <code>ServicesManager</code> 注册，并提供 <code>PlayerTeleport*</code> 生命周期事件。</td></tr><tr><td>PlaceholderAPI</td><td>注册 <code>%yuteleport_*%</code>，覆盖全局状态、玩家冷却、模块可用性、世界规则、费用、warp/home/tpa 统计。</td></tr><tr><td>官方链接</td><td>插件启动和默认配置内置文档、Modrinth、Issue、QQ 群与爱发电链接。</td></tr><tr><td>统计接入</td><td>内置 bStats Bukkit 统计，插件 ID 为 <code>32443</code>。</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>构建或获取发布版 <code>YuTeleport-2.0.0.0-all.jar</code>。</li><li>将 jar 放入服务端 <code>plugins/</code> 目录并启动一次服务器。</li><li>打开 <code>plugins/YuTeleport/config.yml</code>，检查 <code>teleports.defaults.world-access</code>、<code>teleports.rtp.worlds.default</code>、经济和冷却设置。</li><li>普通玩家使用 <code>/rtp</code>、<code>/ytp</code> 或 <code>/yuteleport</code> 在当前世界随机传送。</li><li>按需要启用 <code>/warp</code>、<code>/home</code>、<code>/tpa</code> 和坐标分享，并分配对应权限。</li><li>修改配置或语言文件后执行 <code>/yuteleport reload</code> 热重载。</li></ol><h2 id="适合的服务器" tabindex="-1">适合的服务器 <a class="header-anchor" href="#适合的服务器" aria-label="Permalink to &quot;适合的服务器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐用法</th></tr></thead><tbody><tr><td>生存服</td><td>使用随机传送和 home，减少出生点拥挤，并设置合理冷却和等待打断。</td></tr><tr><td>资源世界</td><td>通过世界白名单只允许资源世界 RTP，并用预缓存降低瞬时搜索开销。</td></tr><tr><td>经济服</td><td>使用 Vault 或 PlayerPoints 对 RTP、warp、home、tpa 和分享分别定价。</td></tr><tr><td>RPG/活动服</td><td>使用 warp、tpa、坐标分享和命令钩子接入活动、任务、广播或日志系统。</td></tr><tr><td>混合端</td><td>保持安全检查开启，按世界配置高度、方块、生物群系和黑白名单。</td></tr></tbody></table><h2 id="当前版本定位" tabindex="-1">当前版本定位 <a class="header-anchor" href="#当前版本定位" aria-label="Permalink to &quot;当前版本定位&quot;">​</a></h2><ul><li>插件版本：<code>2.0.0.0</code></li><li>主类：<code>org.yutay.yuteleport.YuTeleport</code></li><li>主命令：<code>/yuteleport</code></li><li>别名：<code>/ytp</code>、<code>/rtp</code></li><li>模块命令：<code>/warp</code>、<code>/setwarp</code>、<code>/delwarp</code>、<code>/home</code>、<code>/homes</code>、<code>/sethome</code>、<code>/delhome</code>、<code>/tpa</code>、<code>/tpahere</code>、<code>/tpaccept</code>、<code>/tpdeny</code>、<code>/tpacancel</code>、<code>/tpaignore</code>、<code>/tpaall</code></li><li>Java 目标版本：Java 8</li><li>编译 API：Spigot API <code>1.8-R0.1-SNAPSHOT</code></li><li>兼容定位：Minecraft <code>1.8.x-1.26.x</code>，Bukkit/Spigot/Paper/Purpur/Folia 与兼容 Bukkit API 的混合端</li><li>软依赖：Vault、PlaceholderAPI、PlayerPoints</li><li>Folia 声明：<code>folia-supported: true</code></li><li>bStats 插件 ID：<code>32443</code></li><li>默认配置版本：<code>config-version: 19</code></li><li>内置语言：<code>zh_CN</code>、<code>en_US</code></li></ul><h2 id="使用该插件的服务器" tabindex="-1">使用该插件的服务器 <a class="header-anchor" href="#使用该插件的服务器" aria-label="Permalink to &quot;使用该插件的服务器&quot;">​</a></h2>',9)),o(l,{slug:"yu-teleport"})])}const k=i(h,[["render",m]]);export{T as __pageData,k as default};
